<template>
  <section class="page">
    <div class="page-heading"><div><p class="eyebrow">ACCESS CONTROL</p><h1>角色与权限</h1><p class="muted">维护组织 RBAC 角色，并将角色分配给组织成员。授权结果由服务端校验。</p></div><button class="primary-button" @click="showCreate=!showCreate">新建角色</button></div>
    <p v-if="error" class="error-text" role="alert">{{ error }} <span v-if="requestId" class="mono">Request ID: {{ requestId }}</span></p>
    <form v-if="showCreate" class="content-card form-grid" @submit.prevent="createRole"><label>角色编码<input v-model.trim="form.code" required minlength="2" maxlength="80" pattern="[a-z][a-z0-9_]*" placeholder="content_editor"></label><label>角色名称<input v-model.trim="form.name" required maxlength="120"></label><label class="span-all">描述<textarea v-model.trim="form.description" maxlength="500" rows="2"></textarea></label><label class="span-all">权限代码（每行一个）<textarea v-model="permissionText" required rows="6" placeholder="projects:read&#10;projects:write"></textarea><small>必须使用后端已注册的权限代码。未知权限由服务端拒绝。</small></label><div class="span-all form-actions"><button class="primary-button" :disabled="saving">创建角色</button><button type="button" class="secondary-button" @click="showCreate=false">取消</button></div></form>
    <div class="content-card"><div class="card-heading"><h2>角色列表 <span class="count">{{ roles.length }}</span></h2><button class="secondary-button small" @click="load">刷新</button></div><div v-if="loading" class="loading-state">正在读取角色与权限…</div><div v-else-if="!roles.length" class="empty-state">当前组织暂无角色。</div><div v-else class="role-grid"><article v-for="role in roles" :key="role.id" class="role-card"><div class="role-head"><strong>{{ role.name }}</strong><span class="status-pill">{{ role.code }}</span></div><p class="muted">{{ role.description || '暂无描述' }}</p><div class="permission-list"><span v-for="permission in (role.permissions ?? [])" :key="permission">{{ permission }}</span><span v-if="!role.permissions?.length" class="muted">详情接口未返回权限清单</span></div><button class="text-action" @click="selectedRole=role;loadRoleDetail(role.id)">查看详情</button></article></div></div>
    <div class="content-card"><div class="card-heading"><h2>角色分配</h2></div><form class="form-inline" @submit.prevent="assign"><select v-model="assignment.role_id" required><option value="">选择角色</option><option v-for="r in roles" :key="r.id" :value="r.id">{{ r.name }} ({{ r.code }})</option></select><select v-model="assignment.user_id" required><option value="">选择组织用户</option><option v-for="u in users" :key="u.id" :value="u.id">{{ u.full_name }} · {{ u.email }}</option></select><button class="primary-button" :disabled="saving||!assignment.role_id||!assignment.user_id">分配角色</button></form><p class="muted">分配操作会即时改变用户权限，提交前请核对目标账号。</p></div>
    <div v-if="selectedRole" class="modal-backdrop" @click.self="selectedRole=null"><section class="modal-card"><div class="card-heading"><h2>{{ selectedRole.name }}</h2><button class="text-action" @click="selectedRole=null">关闭</button></div><div v-if="detailLoading" class="loading-state">正在读取角色详情…</div><template v-else><p class="muted">{{ selectedRole.description }}</p><div class="permission-list detail-permissions"><span v-for="p in rolePermissions" :key="p">{{ p }}</span></div><p v-if="!rolePermissions.length" class="muted">该角色当前没有返回权限代码。</p></template></section></div>
  </section>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ApiError } from '../../api'
import { rolesApi } from '../../api/roles'
import { usersApi } from '../../api/users'
import type { Role, User } from '../../types/api'
const roles=ref<Role[]>([]),users=ref<User[]>([]),loading=ref(false),saving=ref(false),showCreate=ref(false),error=ref(''),requestId=ref(''),permissionText=ref('')
const selectedRole=ref<Role|null>(null),rolePermissions=ref<string[]>([]),detailLoading=ref(false)
const form=reactive({code:'',name:'',description:''}),assignment=reactive({role_id:'',user_id:''})
function errorMessage(e:unknown){if(e instanceof ApiError){requestId.value=e.requestId??'';return e.status===403?'当前账号没有角色管理权限。':e.message}return e instanceof Error?e.message:'请求失败'}
async function load(){loading.value=true;error.value='';try{const [r,u]=await Promise.all([rolesApi.list(),usersApi.list()]);roles.value=r.data;users.value=u.data.filter(x=>x.is_active)}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function createRole(){saving.value=true;error.value='';try{const permissions=permissionText.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!permissions.length)throw new Error('至少填写一项权限代码');await rolesApi.create({...form,permissions});Object.assign(form,{code:'',name:'',description:''});permissionText.value='';showCreate.value=false;await load()}catch(e){error.value=errorMessage(e)}finally{saving.value=false}}
async function assign(){saving.value=true;error.value='';try{await rolesApi.assign(assignment.role_id,assignment.user_id);assignment.user_id='';error.value='角色分配已由服务端确认。';await load()}catch(e){error.value=errorMessage(e)}finally{saving.value=false}}
async function loadRoleDetail(id:string){detailLoading.value=true;try{const role=(await rolesApi.read(id)).data;rolePermissions.value=role.permissions??[]}catch(e){error.value=errorMessage(e)}finally{detailLoading.value=false}}
onMounted(load)
</script>
<style scoped>
.count{font-size:11px;color:#8994a5;margin-left:6px}.loading-state{padding:24px;color:#7f8b9e}.form-inline{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.form-inline select{min-width:200px;flex:1;border:1px solid #dfe5ee;border-radius:7px;padding:10px;font:inherit;font-size:13px}.modal-backdrop{position:fixed;inset:0;background:#17243b80;z-index:20;display:grid;place-items:center;padding:20px}.modal-card{background:#fff;border-radius:12px;padding:22px;width:min(620px,100%);max-height:85vh;overflow:auto}.detail-permissions{margin-top:18px}@media(max-width:650px){.form-inline{align-items:stretch;flex-direction:column}.form-inline>*{width:100%}}
</style>
